import org.junit.jupiter.params.provider.NullSource;
import org.junit.jupiter.params.provider.ValueSource;

@ResourceLock(Resources.SYSTEM_PROPERTIES)
class ProxyTestIsolationTest {
	private final Map<String, String> previous = new LinkedHashMap<>();

	@BeforeEach
	void rememberCallerProperties() {
		for (String key : new String[] { "http.proxyHost", "http.proxyPort", "http.proxyUser", "http.proxyPassword" }) {
			previous.put(key, System.getProperty(key));
		}
	}

	@AfterEach
	void restoreCallerProperties() {
		previous.forEach((key, value) -> {
			if (value == null) {
				System.clearProperty(key);
			} else {
				System.setProperty(key, value);
			}
		});
	}

	@ParameterizedTest
	@NullSource
	@ValueSource(strings = { "", " ", "previous-host" })
	void restoresExactCallerProperty(String previousValue) {
		System.setProperty("http.proxyHost", "temporary-host");
		new ProxyTest().restoreSystemProperty("http.proxyHost", previousValue);
		assertEquals(previousValue, System.getProperty("http.proxyHost"));
	}

	@Test
	void teardownClosesTheOwnedSessionManager() {
		ProxyTest fixture = new ProxyTest();
		fixture.sessionManager = mock(SharedHttpClientSessionManager.class);
		fixture.tearDown();
		verify(fixture.sessionManager).shutDown();
	}

	@Test
	void failedManagerShutdownStillRestoresAllCallerProperties() {
		ProxyTest fixture = new ProxyTest();
		fixture.sessionManager = mock(SharedHttpClientSessionManager.class);
		fixture.proxyHostOld = "";
		fixture.proxyPortOld = null;
		fixture.proxyUserOld = " ";
		fixture.proxyPasswordOld = "prior-password";
		previous.keySet().forEach(key -> System.setProperty(key, "temporary"));
		IllegalStateException failure = new IllegalStateException("manager shutdown failed");
		doThrow(failure).when(fixture.sessionManager).shutDown();

		assertSame(failure, assertThrows(IllegalStateException.class, fixture::tearDown));
		assertEquals("", System.getProperty("http.proxyHost"));
		assertEquals(null, System.getProperty("http.proxyPort"));
		assertEquals(" ", System.getProperty("http.proxyUser"));
		assertEquals("prior-password", System.getProperty("http.proxyPassword"));
	}
}
